#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int minRemovals(std::vector<int>& nums, int target) {
        std::unordered_map<int, int> dp;
        dp[0] = 0;
        for (int x : nums) {
            auto cur = dp;
            for (const auto& [v, sz] : dp) {
                int nv = v ^ x;
                if (!cur.count(nv) || cur[nv] < sz + 1) {
                    cur[nv] = sz + 1;
                }
            }
            dp = std::move(cur);
        }
        if (!dp.count(target)) return -1;
        return nums.size() - dp[target];
    }
};

import java.util.*;

class Solution {
    public int minRemovals(int[] nums, int target) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int x : nums) {
            Map<Integer, Integer> cur = new HashMap<>(dp);
            for (var entry : dp.entrySet()) {
                int nv = entry.getKey() ^ x;
                int sz = entry.getValue() + 1;
                if (!cur.containsKey(nv) || cur.get(nv) < sz) {
                    cur.put(nv, sz);
                }
            }
            dp = cur;
        }
        if (!dp.containsKey(target)) return -1;
        return nums.length - dp.get(target);
    }
}

